INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C1','kor',2,1,'u5',1,'상황을 보고 마음 짐작하기 — 형이 동생 대신 혼난 장면, 오랜만에 만난 오소리와 너구리처럼 그림과 상황으로 인물의 마음(억울함·미안함·반가움)을 짐작하기',ARRAY['2국02-04']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C2','kor',2,1,'u5',1,'마음을 표현하는 말 — 「반갑다, 반가워!」처럼 마음이 드러난 말을 찾고, 같은 마음을 나타내는 다른 말(보고 싶었어·만나서 기뻐)로 바꾸어 말하기',ARRAY['2국02-04']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C3','kor',2,1,'u5',1,'띄어 읽기의 필요 — 낱말마다 띄면 어색하고, 뜻이 이어지는 낱말을 이어 ∨에서 조금 쉬어 읽으면 내용을 쉽게 이해함을 알기',ARRAY['2국02-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C4','kor',2,1,'u5',3,'「자전거 타기, 성공!」 내용 — 소영이가 놀이터에서 아빠와 자전거 연습을 하며 힘들어도 계속한 까닭, 혼자 타게 되어 뿌듯한 까닭 찾기',ARRAY['2국02-04']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C5','kor',2,1,'u5',3,'인물의 마음을 짐작하는 방법 — 인물에게 있었던 일 정리하기, 인물의 말이나 행동 살피기, 비슷한 내 경험 떠올리기, 다른 인물(아빠)의 마음도 찾기',ARRAY['2국02-04']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C6','kor',2,1,'u5',5,'「강아지 돌보기」 내용과 낱말 — 주영이가 일주일 동안 콩이를 돌본 까닭과 차례를 정리하고, 낯선·설레는·눈치의 뜻 알기',ARRAY['2국02-04']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C7','kor',2,1,'u5',5,'말과 행동으로 마음 짐작하고 나와 견주기 — 「정말 다행이에요」(안심)·「고맙다」(고마움)처럼 말과 행동에서 마음을 찾고, 시간에 따라 바뀌는 마음과 헤어지기 아쉬웠던 내 경험을 견주기',ARRAY['2국02-04']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C8','kor',2,1,'u5',7,'헷갈리기 쉬운 낱말 ① — 마치다/맞히다, 걸음/거름, 다치다/닫히다를 문장의 뜻으로 구분하기',ARRAY['2국04-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C9','kor',2,1,'u5',7,'헷갈리기 쉬운 낱말 ② — 늘이다/느리다, 반드시/반듯이, 때/떼, 붙이다/부치다, 맡다/맞다, 받치다/바치다 등을 문장에 알맞게 쓰기',ARRAY['2국04-02']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C10','kor',2,1,'u5',9,'자연스럽게 띄어 읽는 방법 — 「누가(무엇이)」 다음 ∨, 문장이 길면 「누구를(무엇을)」 뒤 한 번 더, 문장과 문장 사이 ≫, 띄어 읽기는 사람마다 조금 다를 수 있음',ARRAY['2국02-02']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C11','kor',2,1,'u5',9,'「밤 다섯 개」 내용과 인물의 마음 — 또야가 밤을 다 나눠 주고 빈손이 된 일, 눈이 휘둥그레지다·울상을 짓다·입을 비쭉비쭉하다, 또야·친구들·엄마의 마음 짐작하기',ARRAY['2국02-04']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C12','kor',2,1,'u5',11,'마음을 나타내는 말 사용하기 — 마음 낱말과 그 마음이 든 경험으로 마음 사전을 만들고, 역할놀이·생각 구조 그리기로 마음을 말로 표현하기',ARRAY['2국02-04']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C13','kor',2,1,'u5',11,'맞장구치는 말 — 상대의 말을 기분 좋게 받아 주는 말(동의·짧은 내 생각·공감)을 상대의 마음을 생각하며 쓰기(기초 다지기)',ARRAY['2국02-04']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X01','kor',2,'u5',ARRAY['K2-1-u5-C1','K2-1-u5-C5']::text[],'상황을 살피지 않고 겉모습이나 한 장면만 보고 마음을 판단한다','무슨 일이 있었지?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X02','kor',2,'u5',ARRAY['K2-1-u5-C2','K2-1-u5-C12']::text[],'상황과 반대되는 마음을 나타내는 말을 고른다','그 상황이라면 나는?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X03','kor',2,'u5',ARRAY['K2-1-u5-C3','K2-1-u5-C10']::text[],'낱말마다 끊어 띄어 읽어야 또박또박 잘 읽는 것이라 여긴다','뜻이 이어지면 이어서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X04','kor',2,'u5',ARRAY['K2-1-u5-C3','K2-1-u5-C10']::text[],'띄어 읽지 않고 한숨에 읽거나 아무 데서나 쉰다','누가 다음 ∨, 문장 사이 ≫') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X05','kor',2,'u5',ARRAY['K2-1-u5-C4','K2-1-u5-C6','K2-1-u5-C11']::text[],'글에 없는 내용으로 답하거나 일어난 일을 바꿔 안다','그 문장을 글에서 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X06','kor',2,'u5',ARRAY['K2-1-u5-C5']::text[],'인물의 생김새나 제목만으로 마음을 짐작한다','말과 행동을 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X07','kor',2,'u5',ARRAY['K2-1-u5-C5','K2-1-u5-C7']::text[],'자신의 경험과 관련지어 생각하면 안 된다고 여긴다','비슷한 내 경험 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X08','kor',2,'u5',ARRAY['K2-1-u5-C7','K2-1-u5-C11']::text[],'인물의 마음은 처음부터 끝까지 똑같다고 여긴다','일이 바뀌면 마음도 바뀌어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X09','kor',2,'u5',ARRAY['K2-1-u5-C8','K2-1-u5-C9']::text[],'소리가 같으면 어느 표기를 써도 뜻이 같다고 여긴다','표기가 다르면 뜻도 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X10','kor',2,'u5',ARRAY['K2-1-u5-C8']::text[],'마치다/맞히다, 걸음/거름, 다치다/닫히다를 헷갈려 쓴다','문장 전체의 뜻 생각하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X11','kor',2,'u5',ARRAY['K2-1-u5-C9']::text[],'반드시/반듯이, 때/떼, 붙이다/부치다 등을 헷갈려 쓴다','뜻 그림 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X12','kor',2,'u5',ARRAY['K2-1-u5-C10']::text[],'띄어 읽기는 정해진 하나뿐이거나 빨리 읽으려고 하는 것이라 여긴다','뜻이 잘 드러나게, 조금씩 달라도 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X13','kor',2,'u5',ARRAY['K2-1-u5-C6','K2-1-u5-C11']::text[],'낱말이나 표정을 나타내는 말(낯선·울상을 짓다)의 뜻을 헷갈린다','문장에 넣어 표정 지어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X14','kor',2,'u5',ARRAY['K2-1-u5-C7','K2-1-u5-C12']::text[],'내 마음과 인물이나 친구의 마음이 다르면 틀렸다고 여긴다','같은 일에도 마음은 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X15','kor',2,'u5',ARRAY['K2-1-u5-C13']::text[],'상대의 말에 맞장구 대신 무시하거나 반대하는 말을 한다','「정말? 나도!」, 「네 말이 맞아.」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_basic#1','kor',2,1,'u5','L01','g2_1_kor_u5_L01_basic','lesson_basic','K2-1-u5-C1',1,'mc','auto','오소리와 너구리는 어떤 마음인가요?',ARRAY['K2-1-u5-X02']::text[],false,'{"seq":1,"concept":"K2-1-u5-C1","difficulty":1,"kind":"mc","stem":"오소리와 너구리는 어떤 마음인가요?","options":[{"t":"반갑고 행복한 마음","correct":true},{"t":"슬픈 마음","mis":"K2-1-u5-X02"},{"t":"화난 마음","mis":"K2-1-u5-X02"}],"explanation":["반가워요.","154쪽 (2)예요.","예시 답안이에요."],"asset":{"type":"speech","turns":[{"who":"행복 요정","text":"오솔길을 가는데 시끌벅적한 소리가 들렸어요."},{"who":"너구리","text":"오소리야! 이게 얼마 만이야! 반갑다, 반가워!"},{"who":"오소리","text":"너구리야! 반갑다, 정말 반가워!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
