INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_challenge#9','kor',2,1,'u5','L01','g2_1_kor_u5_L01_challenge','lesson_challenge','K2-1-u5-C2',4,'essay','teacher','오랜만에 친구를 만났을 때 반가운 마음을 표현하는 말을 두 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u5-C2","difficulty":4,"kind":"essay","stem":"오랜만에 친구를 만났을 때 반가운 마음을 표현하는 말을 두 가지 쓰세요.","answer_guide":{"answer":"예: 「보고 싶었어!」, 「다시 만나서 정말 기뻐!」","scoring_points":["반가운 마음을 나타내는 말이에요","두 가지를 썼어요"]},"explanation":["표현하는 말이에요.","154쪽 2번이에요.","예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
