INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_basic#1','kor',2,1,'u5','L03','g2_1_kor_u5_L03_basic','lesson_basic','K2-1-u5-C4',1,'mc','auto','소영이가 놀이터에서 한 일은?',ARRAY['K2-1-u5-X05']::text[],false,'{"seq":1,"concept":"K2-1-u5-C4","difficulty":1,"kind":"mc","stem":"소영이가 놀이터에서 한 일은?","options":[{"t":"자전거 타는 연습을 했어요","correct":true},{"t":"미끄럼틀을 탔어요","mis":"K2-1-u5-X05"},{"t":"공놀이를 했어요","mis":"K2-1-u5-X05"}],"explanation":["자전거 연습이에요.","158쪽 (1)이에요.","예시 답안이에요."],"asset":{"type":"passage","lines":["지난주부터 자전거 타는 연습을 하고 있다. 혼자서 멋지게 타고 싶다.","오늘도 아빠와 놀이터로 나갔다. 자꾸만 자전거가 쓰러지려고 했다.","아빠가 자전거 뒤를 잡아 주시며 다시 해 보자고 격려해 주셨다.","나는 너무 힘들었다. 그래도 빨리 배우고 싶어 열심히 연습했다.","아빠는 내가 다칠까 봐 걱정하시며 내일 다시 하자고 하셨다.","「우아, 제가 지금 혼자 타고 있는 거예요?」 「그럼, 아까부터 그랬단다.」","아빠와 나는 손뼉을 마주치며 소리를 질렀다. 참 뿌듯한 하루였다."],"title":"『국어』 156~157쪽 「자전거 타기, 성공!」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
