INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_challenge#6','kor',2,1,'u5','L03','g2_1_kor_u5_L03_challenge','lesson_challenge','K2-1-u5-C4',3,'mc','auto','아빠가 내일 하자고 하셨는데도 소영이가 다시 페달을 밟은 까닭은?',ARRAY['K2-1-u5-X05']::text[],false,'{"seq":6,"concept":"K2-1-u5-C4","difficulty":3,"kind":"mc","stem":"아빠가 내일 하자고 하셨는데도 소영이가 다시 페달을 밟은 까닭은?","options":[{"t":"왠지 오늘은 꼭 성공할 것 같은 느낌이 들어서","correct":true},{"t":"아빠 말을 못 들어서","mis":"K2-1-u5-X05"},{"t":"놀이터가 곧 닫혀서","mis":"K2-1-u5-X05"}],"explanation":["성공할 것 같아요.","157쪽이에요.","글에서 짚어요."],"asset":{"type":"passage","lines":["지난주부터 자전거 타는 연습을 하고 있다. 혼자서 멋지게 타고 싶다.","오늘도 아빠와 놀이터로 나갔다. 자꾸만 자전거가 쓰러지려고 했다.","아빠가 자전거 뒤를 잡아 주시며 다시 해 보자고 격려해 주셨다.","나는 너무 힘들었다. 그래도 빨리 배우고 싶어 열심히 연습했다.","아빠는 내가 다칠까 봐 걱정하시며 내일 다시 하자고 하셨다.","「우아, 제가 지금 혼자 타고 있는 거예요?」 「그럼, 아까부터 그랬단다.」","아빠와 나는 손뼉을 마주치며 소리를 질렀다. 참 뿌듯한 하루였다."],"title":"『국어』 156~157쪽 「자전거 타기, 성공!」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_challenge#7','kor',2,1,'u5','L03','g2_1_kor_u5_L03_challenge','lesson_challenge','K2-1-u5-C5',3,'mc','auto','「발걸음이 가볍다」로 나타낼 수 있는 마음은?',ARRAY['K2-1-u5-X13']::text[],false,'{"seq":7,"concept":"K2-1-u5-C5","difficulty":3,"kind":"mc","stem":"「발걸음이 가볍다」로 나타낼 수 있는 마음은?","options":[{"t":"홀가분하고 기분 좋은 마음","correct":true},{"t":"무겁고 슬픈 마음","mis":"K2-1-u5-X13"},{"t":"발이 아픈 마음","mis":"K2-1-u5-X13"}],"explanation":["홀가분해요.","지도서 208쪽이에요.","대안 활동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_challenge#8','kor',2,1,'u5','L03','g2_1_kor_u5_L03_challenge','lesson_challenge','K2-1-u5-C4',4,'sa','auto','자전거를 혼자 탈 수 있게 된 날, 소영이는 어떤 하루였다고 했나요? 세 글자로 쓰세요(「○○한」).','{}'::text[],false,'{"seq":8,"concept":"K2-1-u5-C4","difficulty":4,"kind":"sa","stem":"자전거를 혼자 탈 수 있게 된 날, 소영이는 어떤 하루였다고 했나요? 세 글자로 쓰세요(「○○한」).","answer":["뿌듯한"],"explanation":["뿌듯한이에요.","157쪽이에요.","글의 끝이에요."],"asset":{"type":"passage","lines":["지난주부터 자전거 타는 연습을 하고 있다. 혼자서 멋지게 타고 싶다.","오늘도 아빠와 놀이터로 나갔다. 자꾸만 자전거가 쓰러지려고 했다.","아빠가 자전거 뒤를 잡아 주시며 다시 해 보자고 격려해 주셨다.","나는 너무 힘들었다. 그래도 빨리 배우고 싶어 열심히 연습했다.","아빠는 내가 다칠까 봐 걱정하시며 내일 다시 하자고 하셨다.","「우아, 제가 지금 혼자 타고 있는 거예요?」 「그럼, 아까부터 그랬단다.」","아빠와 나는 손뼉을 마주치며 소리를 질렀다. 참 뿌듯한 하루였다."],"title":"『국어』 156~157쪽 「자전거 타기, 성공!」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_challenge#9','kor',2,1,'u5','L03','g2_1_kor_u5_L03_challenge','lesson_challenge','K2-1-u5-C5',4,'essay','teacher','「자전거 타기, 성공!」에서 아빠의 마음이 드러난 말이나 행동을 하나 찾고 아빠의 마음을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u5-C5","difficulty":4,"kind":"essay","stem":"「자전거 타기, 성공!」에서 아빠의 마음이 드러난 말이나 행동을 하나 찾고 아빠의 마음을 쓰세요.","answer_guide":{"answer":"예: 자전거 뒤를 잡아 주며 다시 해 보자고 격려해 주셨다 — 소영이를 응원하는 마음","scoring_points":["아빠의 말이나 행동을 찾았어요","아빠의 마음을 썼어요"]},"explanation":["아빠의 마음이에요.","159쪽 4번이에요.","다른 인물이에요."],"asset":{"type":"passage","lines":["지난주부터 자전거 타는 연습을 하고 있다. 혼자서 멋지게 타고 싶다.","오늘도 아빠와 놀이터로 나갔다. 자꾸만 자전거가 쓰러지려고 했다.","아빠가 자전거 뒤를 잡아 주시며 다시 해 보자고 격려해 주셨다.","나는 너무 힘들었다. 그래도 빨리 배우고 싶어 열심히 연습했다.","아빠는 내가 다칠까 봐 걱정하시며 내일 다시 하자고 하셨다.","「우아, 제가 지금 혼자 타고 있는 거예요?」 「그럼, 아까부터 그랬단다.」","아빠와 나는 손뼉을 마주치며 소리를 질렀다. 참 뿌듯한 하루였다."],"title":"『국어』 156~157쪽 「자전거 타기, 성공!」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_challenge#10','kor',2,1,'u5','L03','g2_1_kor_u5_L03_challenge','lesson_challenge','K2-1-u5-C7',4,'essay','teacher','소영이처럼 힘들었지만 끝까지 해낸 경험을 쓰고, 그때의 마음을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u5-C7","difficulty":4,"kind":"essay","stem":"소영이처럼 힘들었지만 끝까지 해낸 경험을 쓰고, 그때의 마음을 쓰세요.","answer_guide":{"answer":"예: 수영에서 처음으로 숨을 참고 끝까지 갔다. 정말 뿌듯하고 신났다.","scoring_points":["비슷한 경험을 썼어요","그때의 마음을 썼어요"]},"explanation":["내 경험이에요.","159쪽이에요.","견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_basic#1','kor',2,1,'u5','L05','g2_1_kor_u5_L05_basic','lesson_basic','K2-1-u5-C6',1,'mc','auto','할머니께서 키우시는 강아지 이름은?',ARRAY['K2-1-u5-X05']::text[],false,'{"seq":1,"concept":"K2-1-u5-C6","difficulty":1,"kind":"mc","stem":"할머니께서 키우시는 강아지 이름은?","options":[{"t":"콩이","correct":true},{"t":"팥이","mis":"K2-1-u5-X05"},{"t":"뭉치","mis":"K2-1-u5-X05"}],"explanation":["콩이예요.","163쪽 (1)이에요.","예시 답안이에요."],"asset":{"type":"passage","lines":["할머니께서 일주일 동안 여행을 떠나셔서 강아지 콩이를 돌보게 되었어요.","나는 가슴이 두근거렸지만, 콩이가 잘 따라 줄지 걱정도 되었어요.","좋아하는 간식을 내밀자 한참 서성이던 콩이가 그제야 먹었어요.","「엄마, 콩이가 우리 집에 적응한 것 같아요. 정말 다행이에요.」","공을 주고받고, 공원에서 발을 맞추며 함께 걸었어요.","마지막 날 나는 아침부터 너무 슬펐어요. 「일주일이 너무 짧은 것 같아요.」","할머니께서는 잘 돌봐 주어서 정말 고맙다고 말씀하셨어요."],"title":"『국어』 160~163쪽 「강아지 돌보기」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_basic#2','kor',2,1,'u5','L05','g2_1_kor_u5_L05_basic','lesson_basic','K2-1-u5-C6',1,'mc','auto','주영이가 강아지를 돌보게 된 까닭은?',ARRAY['K2-1-u5-X05']::text[],false,'{"seq":2,"concept":"K2-1-u5-C6","difficulty":1,"kind":"mc","stem":"주영이가 강아지를 돌보게 된 까닭은?","options":[{"t":"할머니께서 일주일 동안 여행을 떠나셔서","correct":true},{"t":"할머니께서 선물로 주셔서","mis":"K2-1-u5-X05"},{"t":"강아지가 길을 잃어서","mis":"K2-1-u5-X05"}],"explanation":["여행이에요.","163쪽 (2)예요.","예시 답안이에요."],"asset":{"type":"passage","lines":["할머니께서 일주일 동안 여행을 떠나셔서 강아지 콩이를 돌보게 되었어요.","나는 가슴이 두근거렸지만, 콩이가 잘 따라 줄지 걱정도 되었어요.","좋아하는 간식을 내밀자 한참 서성이던 콩이가 그제야 먹었어요.","「엄마, 콩이가 우리 집에 적응한 것 같아요. 정말 다행이에요.」","공을 주고받고, 공원에서 발을 맞추며 함께 걸었어요.","마지막 날 나는 아침부터 너무 슬펐어요. 「일주일이 너무 짧은 것 같아요.」","할머니께서는 잘 돌봐 주어서 정말 고맙다고 말씀하셨어요."],"title":"『국어』 160~163쪽 「강아지 돌보기」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
