INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_challenge#9','kor',2,1,'u5','L05','g2_1_kor_u5_L05_challenge','lesson_challenge','K2-1-u5-C7',4,'essay','teacher','165쪽 — 주영이처럼 누군가와 헤어지기 아쉬웠던 경험을 쓰고, 그때의 마음을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u5-C7","difficulty":4,"kind":"essay","stem":"165쪽 — 주영이처럼 누군가와 헤어지기 아쉬웠던 경험을 쓰고, 그때의 마음을 쓰세요.","answer_guide":{"answer":"예: 친구랑 놀다가 집에 갈 시간이 되었을 때 헤어지기 아쉽고 더 놀고 싶었다.","scoring_points":["경험을 썼어요","그때의 마음을 썼어요"]},"explanation":["자신과 관련짓기예요.","165쪽이에요.","예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_challenge#10','kor',2,1,'u5','L05','g2_1_kor_u5_L05_challenge','lesson_challenge','K2-1-u5-C7',4,'essay','teacher','「강아지 돌보기」에서 주영이의 말이나 행동 하나를 찾아 쓰고, 그때 주영이의 마음을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u5-C7","difficulty":4,"kind":"essay","stem":"「강아지 돌보기」에서 주영이의 말이나 행동 하나를 찾아 쓰고, 그때 주영이의 마음을 쓰세요.","answer_guide":{"answer":"예: 「엄마, 일주일이 너무 짧은 것 같아요.」 — 콩이와 헤어지기 아쉬운 마음","scoring_points":["말이나 행동을 찾았어요","그때의 마음을 썼어요"]},"explanation":["말·행동과 마음이에요.","165쪽 (2)예요.","보기처럼요."],"asset":{"type":"passage","lines":["할머니께서 일주일 동안 여행을 떠나셔서 강아지 콩이를 돌보게 되었어요.","나는 가슴이 두근거렸지만, 콩이가 잘 따라 줄지 걱정도 되었어요.","좋아하는 간식을 내밀자 한참 서성이던 콩이가 그제야 먹었어요.","「엄마, 콩이가 우리 집에 적응한 것 같아요. 정말 다행이에요.」","공을 주고받고, 공원에서 발을 맞추며 함께 걸었어요.","마지막 날 나는 아침부터 너무 슬펐어요. 「일주일이 너무 짧은 것 같아요.」","할머니께서는 잘 돌봐 주어서 정말 고맙다고 말씀하셨어요."],"title":"『국어』 160~163쪽 「강아지 돌보기」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
