INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#5','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C12',3,'mc','auto','아끼는 장난감을 빌려주며 「망가지지 않게 잘 가지고 놀아.」라고 한 마음은?',ARRAY['K2-1-u5-X02']::text[],false,'{"seq":5,"concept":"K2-1-u5-C12","difficulty":3,"kind":"mc","stem":"아끼는 장난감을 빌려주며 「망가지지 않게 잘 가지고 놀아.」라고 한 마음은?","options":[{"t":"장난감이 소중해 걱정되지만 친구와 나누고 싶은 마음","correct":true},{"t":"친구가 미운 마음","mis":"K2-1-u5-X02"},{"t":"장난감이 싫은 마음","mis":"K2-1-u5-X02"}],"explanation":["걱정·나눔이에요.","지도서 230쪽이에요.","역할놀이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#6','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C7',3,'mc','auto','180쪽 글에서 승훈이가 우산을 같이 쓰자고 했을 때 「나」의 마음은?',ARRAY['K2-1-u5-X02']::text[],false,'{"seq":6,"concept":"K2-1-u5-C7","difficulty":3,"kind":"mc","stem":"180쪽 글에서 승훈이가 우산을 같이 쓰자고 했을 때 「나」의 마음은?","options":[{"t":"다행이고 고마운 마음","correct":true},{"t":"부끄럽고 화난 마음","mis":"K2-1-u5-X02"},{"t":"슬픈 마음","mis":"K2-1-u5-X02"}],"explanation":["다행이에요.","180쪽이에요.","말에 드러나요."],"asset":{"type":"passage","lines":["학교를 마치고 운동화를 신고 있는데 갑자기 비가 내리기 시작했다.","「아, 어쩌지? 오늘 우산 안 가져왔는데…….」","나는 어쩔 줄 몰라서 비가 내리는 하늘만 바라보고 있었다.","그때 승훈이 목소리가 들렸다. 「우산 없구나? 나랑 우산 같이 쓰고 가자.」","휴, 정말 다행이었다. 오늘 승훈이와 더 가까워진 기분이다."],"title":"『국어』 180쪽 2번 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#7','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C8',3,'mc','auto','181쪽 — 밥을 다 먹고 「잘 먹었습니다.」 하는 그림에 어울리는 낱말은?',ARRAY['K2-1-u5-X10']::text[],false,'{"seq":7,"concept":"K2-1-u5-C8","difficulty":3,"kind":"mc","stem":"181쪽 — 밥을 다 먹고 「잘 먹었습니다.」 하는 그림에 어울리는 낱말은?","options":[{"t":"마쳤다","correct":true},{"t":"맞혔다","mis":"K2-1-u5-X10"},{"t":"닫혔다","mis":"K2-1-u5-X10"}],"explanation":["마쳤다예요.","181쪽 예시예요.","끝냈어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#8','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C13',4,'sa','auto','상대의 말을 기분 좋게 받아 주는 말을 「○○○치는 말」이라고 해요. 빈칸 세 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-1-u5-C13","difficulty":4,"kind":"sa","stem":"상대의 말을 기분 좋게 받아 주는 말을 「○○○치는 말」이라고 해요. 빈칸 세 글자를 쓰세요.","answer":["맞장구"],"explanation":["맞장구예요.","182쪽이에요.","기초 다지기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#9','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C12',4,'essay','teacher','마음을 나타내는 낱말 하나를 골라, 그 마음이 들었던 나의 경험을 쓰세요(마음 사전 카드).','{}'::text[],false,'{"seq":9,"concept":"K2-1-u5-C12","difficulty":4,"kind":"essay","stem":"마음을 나타내는 낱말 하나를 골라, 그 마음이 들었던 나의 경험을 쓰세요(마음 사전 카드).","answer_guide":{"answer":"예: 설레다 — 소풍 가기 전날 밤, 가방을 싸며 잠이 오지 않았다.","scoring_points":["마음 낱말을 골랐어요","그 마음이 든 경험을 구체적으로 썼어요"]},"explanation":["마음 사전이에요.","178쪽이에요.","붙임 3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#10','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C7',4,'essay','teacher','지도서 235쪽 평가 — 「여우와 두루미」에서 여우가 두루미 집에서 음식을 못 먹고 돌아갈 때의 마음과, 여우에게 전하고 싶은 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u5-C7","difficulty":4,"kind":"essay","stem":"지도서 235쪽 평가 — 「여우와 두루미」에서 여우가 두루미 집에서 음식을 못 먹고 돌아갈 때의 마음과, 여우에게 전하고 싶은 말을 쓰세요.","answer_guide":{"answer":"예: 미안하고 부끄러운 마음 — 「여우야, 다음에는 친구가 먹기 쉬운 그릇에 담아 주자.」","scoring_points":["여우의 마음을 짐작했어요","마음을 배려한 말을 썼어요"]},"explanation":["평가 자료 1이에요.","지도서 235쪽이에요.","배려예요."],"asset":{"type":"passage","lines":["여우는 수프를 넓적한 접시에 담아 두루미에게 내놓았어요.","부리가 뾰족한 두루미는 수프를 먹을 수 없어 접시만 콕콕 찍었어요.","며칠 뒤 두루미는 생선튀김을 목이 긴 호리병에 담아 여우에게 내놓았어요.","여우는 코로 냄새만 맡다가 그제야 잘못을 깨달았어요."],"title":"지도서 235쪽 평가 「여우와 두루미」(이솝) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#1','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C1',1,'mc','auto','오소리와 너구리의 마음은?',ARRAY['K2-1-u5-X02']::text[],false,'{"seq":1,"concept":"K2-1-u5-C1","difficulty":1,"kind":"mc","stem":"오소리와 너구리의 마음은?","options":[{"t":"반갑고 행복한 마음","correct":true},{"t":"슬픈 마음","mis":"K2-1-u5-X02"},{"t":"화난 마음","mis":"K2-1-u5-X02"}],"explanation":["반가워요.","154쪽이에요.","예시예요."],"asset":{"type":"speech","turns":[{"who":"행복 요정","text":"오솔길을 가는데 시끌벅적한 소리가 들렸어요."},{"who":"너구리","text":"오소리야! 이게 얼마 만이야! 반갑다, 반가워!"},{"who":"오소리","text":"너구리야! 반갑다, 정말 반가워!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#2','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C2',1,'mc','auto','반가운 마음을 표현하는 말은?',ARRAY['K2-1-u5-X02']::text[],false,'{"seq":2,"concept":"K2-1-u5-C2","difficulty":1,"kind":"mc","stem":"반가운 마음을 표현하는 말은?","options":[{"t":"「보고 싶었어.」","correct":true},{"t":"「저리 가.」","mis":"K2-1-u5-X02"},{"t":"「귀찮아.」","mis":"K2-1-u5-X02"}],"explanation":["반가워요.","154쪽이에요.","예시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#3','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C3',1,'mc','auto','∨ 표시는 무엇을 나타내나요?',ARRAY['K2-1-u5-X04']::text[],false,'{"seq":3,"concept":"K2-1-u5-C3","difficulty":1,"kind":"mc","stem":"∨ 표시는 무엇을 나타내나요?","options":[{"t":"그곳에서 조금 쉬어 읽어요","correct":true},{"t":"읽기를 끝내요","mis":"K2-1-u5-X04"},{"t":"크게 읽어요","mis":"K2-1-u5-X04"}],"explanation":["쉬어요.","155쪽이에요.","∨예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#4','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C4',1,'mc','auto','소영이가 놀이터에서 한 일은?',ARRAY['K2-1-u5-X05']::text[],false,'{"seq":4,"concept":"K2-1-u5-C4","difficulty":1,"kind":"mc","stem":"소영이가 놀이터에서 한 일은?","options":[{"t":"자전거 타는 연습","correct":true},{"t":"미끄럼틀 타기","mis":"K2-1-u5-X05"},{"t":"공놀이","mis":"K2-1-u5-X05"}],"explanation":["자전거예요.","158쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["지난주부터 자전거 타는 연습을 하고 있다. 혼자서 멋지게 타고 싶다.","오늘도 아빠와 놀이터로 나갔다. 자꾸만 자전거가 쓰러지려고 했다.","아빠가 자전거 뒤를 잡아 주시며 다시 해 보자고 격려해 주셨다.","나는 너무 힘들었다. 그래도 빨리 배우고 싶어 열심히 연습했다.","아빠는 내가 다칠까 봐 걱정하시며 내일 다시 하자고 하셨다.","「우아, 제가 지금 혼자 타고 있는 거예요?」 「그럼, 아까부터 그랬단다.」","아빠와 나는 손뼉을 마주치며 소리를 질렀다. 참 뿌듯한 하루였다."],"title":"『국어』 156~157쪽 「자전거 타기, 성공!」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#5','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C6',1,'mc','auto','할머니의 강아지 이름은?',ARRAY['K2-1-u5-X05']::text[],false,'{"seq":5,"concept":"K2-1-u5-C6","difficulty":1,"kind":"mc","stem":"할머니의 강아지 이름은?","options":[{"t":"콩이","correct":true},{"t":"팥이","mis":"K2-1-u5-X05"},{"t":"뭉치","mis":"K2-1-u5-X05"}],"explanation":["콩이예요.","163쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["할머니께서 일주일 동안 여행을 떠나셔서 강아지 콩이를 돌보게 되었어요.","나는 가슴이 두근거렸지만, 콩이가 잘 따라 줄지 걱정도 되었어요.","좋아하는 간식을 내밀자 한참 서성이던 콩이가 그제야 먹었어요.","「엄마, 콩이가 우리 집에 적응한 것 같아요. 정말 다행이에요.」","공을 주고받고, 공원에서 발을 맞추며 함께 걸었어요.","마지막 날 나는 아침부터 너무 슬펐어요. 「일주일이 너무 짧은 것 같아요.」","할머니께서는 잘 돌봐 주어서 정말 고맙다고 말씀하셨어요."],"title":"『국어』 160~163쪽 「강아지 돌보기」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#6','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C8',1,'mc','auto','「학교를 (    ) 집에 가는 길에」',ARRAY['K2-1-u5-X10']::text[],false,'{"seq":6,"concept":"K2-1-u5-C8","difficulty":1,"kind":"mc","stem":"「학교를 (    ) 집에 가는 길에」","options":[{"t":"마치고","correct":true},{"t":"맞히고","mis":"K2-1-u5-X10"},{"t":"맞추고","mis":"K2-1-u5-X10"}],"explanation":["마치고예요.","167쪽이에요.","끝내요."],"asset":{"type":"passage","lines":["어제 학교를 마치고 집에 가는 길에 넘어진 나를 네가 도와주었잖아.","삼촌이 오시기로 한 날이라 마음이 들떠서 자꾸만 걸음이 빨라졌어.","그러다 꽈당 넘어졌고, 다친 무릎이 아파서 눈물이 핑 돌았지.","윤아야, 그때 도와줘서 정말 고마워."],"title":"『국어』 166쪽 예린이의 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
