INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#14','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C13',2,'mc','auto','「음식을 골고루 먹어야 해.」에 맞장구치는 말은?',ARRAY['K2-1-u5-X15']::text[],false,'{"seq":14,"concept":"K2-1-u5-C13","difficulty":2,"kind":"mc","stem":"「음식을 골고루 먹어야 해.」에 맞장구치는 말은?","options":[{"t":"「네 말이 맞아.」","correct":true},{"t":"「싫어.」","mis":"K2-1-u5-X15"},{"t":"「몰라.」","mis":"K2-1-u5-X15"}],"explanation":["동의해요.","182쪽이에요.","예시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#15','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C5',2,'mc','auto','소영이에게 있었던 일을 차례대로 정리한 것은?',ARRAY['K2-1-u5-X05']::text[],false,'{"seq":15,"concept":"K2-1-u5-C5","difficulty":2,"kind":"mc","stem":"소영이에게 있었던 일을 차례대로 정리한 것은?","options":[{"t":"놀이터로 나감 → 연습을 함 → 혼자서 타게 됨","correct":true},{"t":"혼자서 타게 됨 → 놀이터로 나감 → 연습","mis":"K2-1-u5-X05"},{"t":"연습 → 혼자서 타게 됨 → 놀이터로 나감","mis":"K2-1-u5-X05"}],"explanation":["차례예요.","158쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["지난주부터 자전거 타는 연습을 하고 있다. 혼자서 멋지게 타고 싶다.","오늘도 아빠와 놀이터로 나갔다. 자꾸만 자전거가 쓰러지려고 했다.","아빠가 자전거 뒤를 잡아 주시며 다시 해 보자고 격려해 주셨다.","나는 너무 힘들었다. 그래도 빨리 배우고 싶어 열심히 연습했다.","아빠는 내가 다칠까 봐 걱정하시며 내일 다시 하자고 하셨다.","「우아, 제가 지금 혼자 타고 있는 거예요?」 「그럼, 아까부터 그랬단다.」","아빠와 나는 손뼉을 마주치며 소리를 질렀다. 참 뿌듯한 하루였다."],"title":"『국어』 156~157쪽 「자전거 타기, 성공!」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#16','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C5',2,'match','auto','소영이의 말이나 행동과 마음을 이어 보세요.','{}'::text[],false,'{"seq":16,"concept":"K2-1-u5-C5","difficulty":2,"kind":"match","stem":"소영이의 말이나 행동과 마음을 이어 보세요.","pairs":[{"l":"「우아, 제가 지금 혼자 타고 있는 거예요?」","r":"신기하고 기쁜 마음"},{"l":"힘들었지만 열심히 연습했다","r":"포기하지 않고 노력하는 마음"},{"l":"손뼉을 마주치며 소리를 질렀다","r":"정말 기뻐하는 마음"}],"mis":"K2-1-u5-X06","explanation":["말·행동과 마음이에요.","159쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["지난주부터 자전거 타는 연습을 하고 있다. 혼자서 멋지게 타고 싶다.","오늘도 아빠와 놀이터로 나갔다. 자꾸만 자전거가 쓰러지려고 했다.","아빠가 자전거 뒤를 잡아 주시며 다시 해 보자고 격려해 주셨다.","나는 너무 힘들었다. 그래도 빨리 배우고 싶어 열심히 연습했다.","아빠는 내가 다칠까 봐 걱정하시며 내일 다시 하자고 하셨다.","「우아, 제가 지금 혼자 타고 있는 거예요?」 「그럼, 아까부터 그랬단다.」","아빠와 나는 손뼉을 마주치며 소리를 질렀다. 참 뿌듯한 하루였다."],"title":"『국어』 156~157쪽 「자전거 타기, 성공!」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
