INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#19','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C3',3,'ox','auto','낱말마다 모두 띄어 읽어야 가장 자연스럽다.',ARRAY['K2-1-u5-X03']::text[],false,'{"seq":19,"concept":"K2-1-u5-C3","difficulty":3,"kind":"ox","stem":"낱말마다 모두 띄어 읽어야 가장 자연스럽다.","answer":"X","reason_options":[{"t":"뜻이 이어지는 낱말을 이어 읽어야 내용을 쉽게 이해할 수 있어서","correct":true},{"t":"낱말마다 띄어야 또박또박해서","mis":"K2-1-u5-X03"}],"mis":"K2-1-u5-X03","explanation":["이어서 읽어요.","155쪽이에요.","지도서 207쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#20','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C10',3,'mc','auto','「애들은∨삶은 밤을 까먹기∨시작했어요.」처럼 읽으면 더 강조되는 것은?',ARRAY['K2-1-u5-X12']::text[],false,'{"seq":20,"concept":"K2-1-u5-C10","difficulty":3,"kind":"mc","stem":"「애들은∨삶은 밤을 까먹기∨시작했어요.」처럼 읽으면 더 강조되는 것은?","options":[{"t":"밤을 까먹는 행동","correct":true},{"t":"밤의 개수","mis":"K2-1-u5-X12"},{"t":"애들의 이름","mis":"K2-1-u5-X12"}],"explanation":["행동이에요.","지도서 223쪽이에요.","강조가 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#21','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C7',3,'mc','auto','「강아지 돌보기」에서 주영이의 마음이 바뀐 차례는?',ARRAY['K2-1-u5-X08']::text[],false,'{"seq":21,"concept":"K2-1-u5-C7","difficulty":3,"kind":"mc","stem":"「강아지 돌보기」에서 주영이의 마음이 바뀐 차례는?","options":[{"t":"설렘·걱정 → 안심 → 기쁨 → 아쉬움","correct":true},{"t":"아쉬움 → 설렘 → 안심","mis":"K2-1-u5-X08"},{"t":"처음부터 끝까지 슬픔","mis":"K2-1-u5-X08"}],"explanation":["바뀌는 마음이에요.","160~163쪽이에요.","지도서 205쪽이에요."],"asset":{"type":"passage","lines":["할머니께서 일주일 동안 여행을 떠나셔서 강아지 콩이를 돌보게 되었어요.","나는 가슴이 두근거렸지만, 콩이가 잘 따라 줄지 걱정도 되었어요.","좋아하는 간식을 내밀자 한참 서성이던 콩이가 그제야 먹었어요.","「엄마, 콩이가 우리 집에 적응한 것 같아요. 정말 다행이에요.」","공을 주고받고, 공원에서 발을 맞추며 함께 걸었어요.","마지막 날 나는 아침부터 너무 슬펐어요. 「일주일이 너무 짧은 것 같아요.」","할머니께서는 잘 돌봐 주어서 정말 고맙다고 말씀하셨어요."],"title":"『국어』 160~163쪽 「강아지 돌보기」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#22','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C9',3,'mc','auto','「프라이팬에 기름을 두르고 달걀을 (    ).」',ARRAY['K2-1-u5-X11']::text[],false,'{"seq":22,"concept":"K2-1-u5-C9","difficulty":3,"kind":"mc","stem":"「프라이팬에 기름을 두르고 달걀을 (    ).」","options":[{"t":"부쳤다","correct":true},{"t":"붙였다","mis":"K2-1-u5-X11"},{"t":"부셨다","mis":"K2-1-u5-X11"}],"explanation":["부쳤다예요.","168쪽이에요.","익혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#23','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C1',4,'sa','auto','내 잘못이 아닌데 혼나서 속상하고 분한 마음을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u5-C1","difficulty":4,"kind":"sa","stem":"내 잘못이 아닌데 혼나서 속상하고 분한 마음을 두 글자로 쓰세요.","answer":["억울"],"explanation":["억울이에요.","153쪽이에요.","예시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#24','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C7',4,'essay','teacher','지도서 234~235쪽 평가 — 「여우와 두루미」에서 두루미가 수프를 못 먹고 침만 삼키다 돌아갈 때의 마음과, 두루미에게 전하고 싶은 말을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u5-C7","difficulty":4,"kind":"essay","stem":"지도서 234~235쪽 평가 — 「여우와 두루미」에서 두루미가 수프를 못 먹고 침만 삼키다 돌아갈 때의 마음과, 두루미에게 전하고 싶은 말을 쓰세요.","answer_guide":{"answer":"예: 속상하고 서운한 마음 — 「두루미야, 많이 속상했지? 여우도 이제 잘못을 깨달았을 거야.」","scoring_points":["두루미의 마음을 짐작했어요","마음을 배려한 말을 썼어요"]},"explanation":["평가 자료 1이에요.","지도서 235쪽이에요.","배려예요."],"asset":{"type":"passage","lines":["여우는 수프를 넓적한 접시에 담아 두루미에게 내놓았어요.","부리가 뾰족한 두루미는 수프를 먹을 수 없어 접시만 콕콕 찍었어요.","며칠 뒤 두루미는 생선튀김을 목이 긴 호리병에 담아 여우에게 내놓았어요.","여우는 코로 냄새만 맡다가 그제야 잘못을 깨달았어요."],"title":"지도서 235쪽 평가 「여우와 두루미」(이솝) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#25','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C9',4,'essay','teacher','지도서 236~237쪽 평가 — 「맞히다·닫히다·걸음·늘이다·떼·반듯이·붙이다」 가운데 두 개를 골라 각각 알맞은 문장을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u5-C9","difficulty":4,"kind":"essay","stem":"지도서 236~237쪽 평가 — 「맞히다·닫히다·걸음·늘이다·떼·반듯이·붙이다」 가운데 두 개를 골라 각각 알맞은 문장을 쓰세요.","answer_guide":{"answer":"예: 걸음 — 몇 걸음만 가면 학교다. / 붙이다 — 공책에 이름표를 붙였다.","scoring_points":["낱말 두 개를 골랐어요","뜻에 맞게 문장을 만들었어요"]},"explanation":["평가 자료 2예요.","지도서 237쪽이에요.","문장 만들기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
