INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#3','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C10',1,'mc','auto','≫ 표시는 어떻게 읽나요?',ARRAY['K2-1-u5-X04']::text[],false,'{"seq":3,"concept":"K2-1-u5-C10","difficulty":1,"kind":"mc","stem":"≫ 표시는 어떻게 읽나요?","options":[{"t":"∨보다 조금 더 쉬어 읽어요","correct":true},{"t":"건너뛰어요","mis":"K2-1-u5-X04"},{"t":"∨보다 짧게 쉬어요","mis":"K2-1-u5-X04"}],"explanation":["더 쉬어요.","170쪽이에요.","문장 사이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#4','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C4',1,'mc','auto','소영이는 누구와 연습했나요?',ARRAY['K2-1-u5-X05']::text[],false,'{"seq":4,"concept":"K2-1-u5-C4","difficulty":1,"kind":"mc","stem":"소영이는 누구와 연습했나요?","options":[{"t":"아빠","correct":true},{"t":"엄마","mis":"K2-1-u5-X05"},{"t":"형","mis":"K2-1-u5-X05"}],"explanation":["아빠예요.","156쪽이에요.","글에서 짚어요."],"asset":{"type":"passage","lines":["지난주부터 자전거 타는 연습을 하고 있다. 혼자서 멋지게 타고 싶다.","오늘도 아빠와 놀이터로 나갔다. 자꾸만 자전거가 쓰러지려고 했다.","아빠가 자전거 뒤를 잡아 주시며 다시 해 보자고 격려해 주셨다.","나는 너무 힘들었다. 그래도 빨리 배우고 싶어 열심히 연습했다.","아빠는 내가 다칠까 봐 걱정하시며 내일 다시 하자고 하셨다.","「우아, 제가 지금 혼자 타고 있는 거예요?」 「그럼, 아까부터 그랬단다.」","아빠와 나는 손뼉을 마주치며 소리를 질렀다. 참 뿌듯한 하루였다."],"title":"『국어』 156~157쪽 「자전거 타기, 성공!」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#5','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C6',1,'mc','auto','주영이가 강아지를 돌보게 된 까닭은?',ARRAY['K2-1-u5-X05']::text[],false,'{"seq":5,"concept":"K2-1-u5-C6","difficulty":1,"kind":"mc","stem":"주영이가 강아지를 돌보게 된 까닭은?","options":[{"t":"할머니께서 일주일 동안 여행을 떠나셔서","correct":true},{"t":"선물로 받아서","mis":"K2-1-u5-X05"},{"t":"길을 잃어서","mis":"K2-1-u5-X05"}],"explanation":["여행이에요.","163쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["할머니께서 일주일 동안 여행을 떠나셔서 강아지 콩이를 돌보게 되었어요.","나는 가슴이 두근거렸지만, 콩이가 잘 따라 줄지 걱정도 되었어요.","좋아하는 간식을 내밀자 한참 서성이던 콩이가 그제야 먹었어요.","「엄마, 콩이가 우리 집에 적응한 것 같아요. 정말 다행이에요.」","공을 주고받고, 공원에서 발을 맞추며 함께 걸었어요.","마지막 날 나는 아침부터 너무 슬펐어요. 「일주일이 너무 짧은 것 같아요.」","할머니께서는 잘 돌봐 주어서 정말 고맙다고 말씀하셨어요."],"title":"『국어』 160~163쪽 「강아지 돌보기」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
