INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#23','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C6',4,'sa','auto','주영이가 콩이를 돌본 기간을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u5-C6","difficulty":4,"kind":"sa","stem":"주영이가 콩이를 돌본 기간을 세 글자로 쓰세요.","answer":["일주일","일 주일"],"explanation":["일주일이에요.","160쪽이에요.","글에서 짚어요."],"asset":{"type":"passage","lines":["할머니께서 일주일 동안 여행을 떠나셔서 강아지 콩이를 돌보게 되었어요.","나는 가슴이 두근거렸지만, 콩이가 잘 따라 줄지 걱정도 되었어요.","좋아하는 간식을 내밀자 한참 서성이던 콩이가 그제야 먹었어요.","「엄마, 콩이가 우리 집에 적응한 것 같아요. 정말 다행이에요.」","공을 주고받고, 공원에서 발을 맞추며 함께 걸었어요.","마지막 날 나는 아침부터 너무 슬펐어요. 「일주일이 너무 짧은 것 같아요.」","할머니께서는 잘 돌봐 주어서 정말 고맙다고 말씀하셨어요."],"title":"『국어』 160~163쪽 「강아지 돌보기」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#24','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C7',4,'essay','teacher','「여우와 두루미」에서 여우가 잘못을 깨닫고 돌아갈 때의 마음과, 여우에게 전하고 싶은 말을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u5-C7","difficulty":4,"kind":"essay","stem":"「여우와 두루미」에서 여우가 잘못을 깨닫고 돌아갈 때의 마음과, 여우에게 전하고 싶은 말을 쓰세요.","answer_guide":{"answer":"예: 미안하고 부끄러운 마음 — 「여우야, 다음에는 친구가 먹기 쉬운 그릇에 담아 주자.」","scoring_points":["여우의 마음을 짐작했어요","마음을 배려한 말을 썼어요"]},"explanation":["평가 자료 1이에요.","지도서 235쪽이에요.","배려예요."],"asset":{"type":"passage","lines":["여우는 수프를 넓적한 접시에 담아 두루미에게 내놓았어요.","부리가 뾰족한 두루미는 수프를 먹을 수 없어 접시만 콕콕 찍었어요.","며칠 뒤 두루미는 생선튀김을 목이 긴 호리병에 담아 여우에게 내놓았어요.","여우는 코로 냄새만 맡다가 그제야 잘못을 깨달았어요."],"title":"지도서 235쪽 평가 「여우와 두루미」(이솝) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#25','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C9',4,'essay','teacher','「반드시」와 「반듯이」를 각각 넣어 알맞은 문장을 하나씩 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u5-C9","difficulty":4,"kind":"essay","stem":"「반드시」와 「반듯이」를 각각 넣어 알맞은 문장을 하나씩 쓰세요.","answer_guide":{"answer":"예: 내일은 반드시 일찍 일어날 것이다. / 의자에 반듯이 앉았다.","scoring_points":["「반드시」를 알맞게 썼어요","「반듯이」를 알맞게 썼어요"]},"explanation":["문장 만들기예요.","169쪽이에요.","평가 자료 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
