INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#14','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C12',2,'mc','auto','친구와 같은 마음 낱말을 골랐을 때 알맞은 생각은?',ARRAY['K2-1-u5-X14']::text[],false,'{"seq":14,"concept":"K2-1-u5-C12","difficulty":2,"kind":"mc","stem":"친구와 같은 마음 낱말을 골랐을 때 알맞은 생각은?","options":[{"t":"그 마음이 드는 때는 사람마다 달라서 모으면 좋아요","correct":true},{"t":"같으면 틀려요","mis":"K2-1-u5-X14"},{"t":"하나만 남겨요","mis":"K2-1-u5-X14"}],"explanation":["사람마다 달라요.","지도서 229쪽이에요.","우리 반 마음 사전이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#15','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C6',2,'mc','auto','주영이가 콩이를 데리고 산책을 간 곳은?',ARRAY['K2-1-u5-X05']::text[],false,'{"seq":15,"concept":"K2-1-u5-C6","difficulty":2,"kind":"mc","stem":"주영이가 콩이를 데리고 산책을 간 곳은?","options":[{"t":"집 근처 공원","correct":true},{"t":"할머니 댁","mis":"K2-1-u5-X05"},{"t":"학교","mis":"K2-1-u5-X05"}],"explanation":["공원이에요.","162쪽이에요.","글에서 짚어요."],"asset":{"type":"passage","lines":["할머니께서 일주일 동안 여행을 떠나셔서 강아지 콩이를 돌보게 되었어요.","나는 가슴이 두근거렸지만, 콩이가 잘 따라 줄지 걱정도 되었어요.","좋아하는 간식을 내밀자 한참 서성이던 콩이가 그제야 먹었어요.","「엄마, 콩이가 우리 집에 적응한 것 같아요. 정말 다행이에요.」","공을 주고받고, 공원에서 발을 맞추며 함께 걸었어요.","마지막 날 나는 아침부터 너무 슬펐어요. 「일주일이 너무 짧은 것 같아요.」","할머니께서는 잘 돌봐 주어서 정말 고맙다고 말씀하셨어요."],"title":"『국어』 160~163쪽 「강아지 돌보기」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
