INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#19','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C5',3,'ox','auto','자신의 경험과 관련지어 생각하면 인물의 마음을 짐작하는 데 방해가 된다.',ARRAY['K2-1-u5-X07']::text[],false,'{"seq":19,"concept":"K2-1-u5-C5","difficulty":3,"kind":"ox","stem":"자신의 경험과 관련지어 생각하면 인물의 마음을 짐작하는 데 방해가 된다.","answer":"X","reason_options":[{"t":"비슷한 경험을 떠올리면 인물의 마음을 더 잘 짐작할 수 있어서","correct":true},{"t":"인물과 나는 관계가 없어서","mis":"K2-1-u5-X07"}],"mis":"K2-1-u5-X07","explanation":["경험이 도와요.","180쪽이에요.","미소의 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
