INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#23','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C13',4,'sa','auto','상대의 말을 기분 좋게 받아 주는 말을 「○○○치는 말」이라고 해요. 빈칸 세 글자를 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u5-C13","difficulty":4,"kind":"sa","stem":"상대의 말을 기분 좋게 받아 주는 말을 「○○○치는 말」이라고 해요. 빈칸 세 글자를 쓰세요.","answer":["맞장구"],"explanation":["맞장구예요.","182쪽이에요.","기초 다지기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#24','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C7',4,'essay','teacher','주영이처럼 누군가와 헤어지기 아쉬웠던 경험을 쓰고, 그때의 마음을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u5-C7","difficulty":4,"kind":"essay","stem":"주영이처럼 누군가와 헤어지기 아쉬웠던 경험을 쓰고, 그때의 마음을 쓰세요.","answer_guide":{"answer":"예: 친구랑 놀다가 집에 갈 시간이 되었을 때 헤어지기 아쉽고 더 놀고 싶었다.","scoring_points":["경험을 썼어요","그때의 마음을 썼어요"]},"explanation":["자신과 관련짓기예요.","165쪽이에요.","예시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
