INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#3','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C10',1,'mc','auto','문장과 문장 사이에서는 어떻게 읽나요?',ARRAY['K2-1-u5-X04']::text[],false,'{"seq":3,"concept":"K2-1-u5-C10","difficulty":1,"kind":"mc","stem":"문장과 문장 사이에서는 어떻게 읽나요?","options":[{"t":"조금 더 길게 쉬어 읽어요","correct":true},{"t":"쉬지 않고 이어 읽어요","mis":"K2-1-u5-X04"},{"t":"처음부터 다시 읽어요","mis":"K2-1-u5-X04"}],"explanation":["더 쉬어요.","170쪽이에요.","≫예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#4','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C4',1,'mc','auto','소영이가 힘들어도 연습한 까닭은?',ARRAY['K2-1-u5-X05']::text[],false,'{"seq":4,"concept":"K2-1-u5-C4","difficulty":1,"kind":"mc","stem":"소영이가 힘들어도 연습한 까닭은?","options":[{"t":"빨리 배우고 싶어서","correct":true},{"t":"혼날까 봐","mis":"K2-1-u5-X05"},{"t":"놀 것이 없어서","mis":"K2-1-u5-X05"}],"explanation":["배우고 싶어요.","158쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["지난주부터 자전거 타는 연습을 하고 있다. 혼자서 멋지게 타고 싶다.","오늘도 아빠와 놀이터로 나갔다. 자꾸만 자전거가 쓰러지려고 했다.","아빠가 자전거 뒤를 잡아 주시며 다시 해 보자고 격려해 주셨다.","나는 너무 힘들었다. 그래도 빨리 배우고 싶어 열심히 연습했다.","아빠는 내가 다칠까 봐 걱정하시며 내일 다시 하자고 하셨다.","「우아, 제가 지금 혼자 타고 있는 거예요?」 「그럼, 아까부터 그랬단다.」","아빠와 나는 손뼉을 마주치며 소리를 질렀다. 참 뿌듯한 하루였다."],"title":"『국어』 156~157쪽 「자전거 타기, 성공!」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
