INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#9','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C5',2,'mc','auto','인물의 마음을 짐작하며 읽으면 좋은 점은?',ARRAY['K2-1-u5-X06']::text[],false,'{"seq":9,"concept":"K2-1-u5-C5","difficulty":2,"kind":"mc","stem":"인물의 마음을 짐작하며 읽으면 좋은 점은?","options":[{"t":"글을 더 잘 이해하고 마음이 생생해요","correct":true},{"t":"빨리 끝나요","mis":"K2-1-u5-X06"},{"t":"글자를 몰라도 돼요","mis":"K2-1-u5-X06"}],"explanation":["잘 이해해요.","159쪽이에요.","예시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#10','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C7',2,'mc','auto','「나는 가슴이 두근거렸어요.」에 드러난 마음은?',ARRAY['K2-1-u5-X02']::text[],false,'{"seq":10,"concept":"K2-1-u5-C7","difficulty":2,"kind":"mc","stem":"「나는 가슴이 두근거렸어요.」에 드러난 마음은?","options":[{"t":"설레는 마음","correct":true},{"t":"무서운 마음","mis":"K2-1-u5-X02"},{"t":"지루한 마음","mis":"K2-1-u5-X02"}],"explanation":["설레요.","160쪽이에요.","몸으로 나타낸 말이에요."],"asset":{"type":"passage","lines":["할머니께서 일주일 동안 여행을 떠나셔서 강아지 콩이를 돌보게 되었어요.","나는 가슴이 두근거렸지만, 콩이가 잘 따라 줄지 걱정도 되었어요.","좋아하는 간식을 내밀자 한참 서성이던 콩이가 그제야 먹었어요.","「엄마, 콩이가 우리 집에 적응한 것 같아요. 정말 다행이에요.」","공을 주고받고, 공원에서 발을 맞추며 함께 걸었어요.","마지막 날 나는 아침부터 너무 슬펐어요. 「일주일이 너무 짧은 것 같아요.」","할머니께서는 잘 돌봐 주어서 정말 고맙다고 말씀하셨어요."],"title":"『국어』 160~163쪽 「강아지 돌보기」 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
