INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#12','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C10',2,'mc','auto','자연스럽게 띄어 읽은 것은?',ARRAY['K2-1-u5-X03','K2-1-u5-X04']::text[],false,'{"seq":12,"concept":"K2-1-u5-C10","difficulty":2,"kind":"mc","stem":"자연스럽게 띄어 읽은 것은?","options":[{"t":"나는 ∨ 어쩔 줄 몰라서 ∨ 비가 내리는 하늘만 ∨ 바라보고 있었다.","correct":true},{"t":"나는 ∨ 어쩔 ∨ 줄 ∨ 몰라서 ∨ 비가 ∨ 내리는","mis":"K2-1-u5-X03"},{"t":"나는어쩔줄몰라서비가내리는하늘만","mis":"K2-1-u5-X04"}],"explanation":["뜻 덩어리예요.","180쪽이에요.","2번이에요."],"asset":{"type":"passage","lines":["학교를 마치고 운동화를 신고 있는데 갑자기 비가 내리기 시작했다.","「아, 어쩌지? 오늘 우산 안 가져왔는데…….」","나는 어쩔 줄 몰라서 비가 내리는 하늘만 바라보고 있었다.","그때 승훈이 목소리가 들렸다. 「우산 없구나? 나랑 우산 같이 쓰고 가자.」","휴, 정말 다행이었다. 오늘 승훈이와 더 가까워진 기분이다."],"title":"『국어』 180쪽 2번 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
