INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#15','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C8',2,'mc','auto','예린이의 걸음이 빨라진 까닭은?',ARRAY['K2-1-u5-X05']::text[],false,'{"seq":15,"concept":"K2-1-u5-C8","difficulty":2,"kind":"mc","stem":"예린이의 걸음이 빨라진 까닭은?","options":[{"t":"삼촌이 오시기로 한 날이라 마음이 들떠서","correct":true},{"t":"비가 와서","mis":"K2-1-u5-X05"},{"t":"시합을 해서","mis":"K2-1-u5-X05"}],"explanation":["들떴어요.","166쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["어제 학교를 마치고 집에 가는 길에 넘어진 나를 네가 도와주었잖아.","삼촌이 오시기로 한 날이라 마음이 들떠서 자꾸만 걸음이 빨라졌어.","그러다 꽈당 넘어졌고, 다친 무릎이 아파서 눈물이 핑 돌았지.","윤아야, 그때 도와줘서 정말 고마워."],"title":"『국어』 166쪽 예린이의 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
