INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#24','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C11',4,'essay','teacher','「밤 다섯 개」의 인물 가운데 한 명을 골라 하고 싶은 말을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u5-C11","difficulty":4,"kind":"essay","stem":"「밤 다섯 개」의 인물 가운데 한 명을 골라 하고 싶은 말을 쓰세요.","answer_guide":{"answer":"예: 또야에게 — 친구들에게 밤을 다 나누어 준 너의 마음이 정말 따뜻해.","scoring_points":["인물을 골랐어요","인물의 마음을 생각한 말을 썼어요"]},"explanation":["인물과 대화하기예요.","176쪽이에요.","예시예요."],"asset":{"type":"scene","icon":"🌰","text":"「밤 다섯 개」(권정생) — 또야가 받은 삶은 밤 다섯 개를 친구 다섯에게 다 나눠 주고 빈손이 되어 울어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#25','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C10',4,'essay','teacher','「학교를 마치고 집에 가려고 운동화를 신고 있는데 갑자기 비가 내리기 시작했다.」를 ∨로 띄어 읽을 곳을 나타내 다시 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u5-C10","difficulty":4,"kind":"essay","stem":"「학교를 마치고 집에 가려고 운동화를 신고 있는데 갑자기 비가 내리기 시작했다.」를 ∨로 띄어 읽을 곳을 나타내 다시 쓰세요.","answer_guide":{"answer":"예: 학교를 마치고 ∨ 집에 가려고 ∨ 운동화를 신고 있는데 ∨ 갑자기 비가 ∨ 내리기 시작했다.","scoring_points":["뜻 덩어리마다 ∨를 했어요","낱말마다 끊지 않았어요"]},"explanation":["띄어 읽기예요.","180쪽이에요.","자연스럽게요."],"asset":{"type":"passage","lines":["학교를 마치고 운동화를 신고 있는데 갑자기 비가 내리기 시작했다.","「아, 어쩌지? 오늘 우산 안 가져왔는데…….」","나는 어쩔 줄 몰라서 비가 내리는 하늘만 바라보고 있었다.","그때 승훈이 목소리가 들렸다. 「우산 없구나? 나랑 우산 같이 쓰고 가자.」","휴, 정말 다행이었다. 오늘 승훈이와 더 가까워진 기분이다."],"title":"『국어』 180쪽 2번 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
